const header=document.querySelector('[data-header]');const menuButton=document.querySelector('.menu-button');const nav=document.querySelector('#main-nav');const progress=document.querySelector('[data-scroll-progress]');const hero=document.querySelector('.hero');const updateScrollUI=()=>{header?.classList.toggle('is-scrolled',window.scrollY>30);const max=document.documentElement.scrollHeight-window.innerHeight;progress?.style.setProperty('transform',`scaleX(${max>0?Math.min(window.scrollY/max,1):0})`);hero?.style.setProperty('--hero-shift',String(Math.min(window.scrollY,900)))};updateScrollUI();window.addEventListener('scroll',updateScrollUI,{passive:true});
const closeMenu=()=>{if(!menuButton||!nav)return;menuButton.setAttribute('aria-expanded','false');nav.classList.remove('is-open');document.body.classList.remove('menu-open')};menuButton?.addEventListener('click',()=>{const willOpen=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(willOpen));nav.classList.toggle('is-open',willOpen);document.body.classList.toggle('menu-open',willOpen)});nav?.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));
const piecePanels=[...document.querySelectorAll('[data-piece]')];const pieceButtons=[...document.querySelectorAll('[data-piece-button]')];pieceButtons.forEach(button=>button.addEventListener('click',()=>{const index=button.dataset.pieceButton;pieceButtons.forEach(item=>item.classList.toggle('is-active',item===button));piecePanels.forEach(panel=>panel.classList.toggle('is-active',panel.dataset.piece===index))}));
const revealItems=[...document.querySelectorAll('[data-reveal]')];const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;if(reducedMotion||!('IntersectionObserver'in window)){revealItems.forEach(item=>item.classList.add('is-visible'))}else{const observer=new IntersectionObserver((entries,instance)=>{entries.forEach(entry=>{if(!entry.isIntersecting)return;entry.target.classList.add('is-visible');instance.unobserve(entry.target)})},{threshold:.08,rootMargin:'0px 0px -4% 0px'});revealItems.forEach((item,index)=>{item.style.transitionDelay=`${Math.min(index%4*70,210)}ms`;observer.observe(item)});const revealPassedItems=()=>revealItems.forEach(item=>{if(item.getBoundingClientRect().top<window.innerHeight*.96)item.classList.add('is-visible')});revealPassedItems();window.addEventListener('scroll',revealPassedItems,{passive:true})}
const navLinks=[...document.querySelectorAll('#main-nav a[href^="#"]')];const navTargets=navLinks.map(link=>document.querySelector(link.getAttribute('href'))).filter(Boolean);if('IntersectionObserver'in window){const navObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;navLinks.forEach(link=>link.classList.toggle('is-current',link.getAttribute('href')===`#${entry.target.id}`))}),{rootMargin:'-35% 0px -55% 0px'});navTargets.forEach(section=>navObserver.observe(section))}
document.querySelectorAll('.spotlight-card').forEach(card=>card.addEventListener('pointermove',event=>{const box=card.getBoundingClientRect();card.style.setProperty('--mx',`${event.clientX-box.left}px`);card.style.setProperty('--my',`${event.clientY-box.top}px`)}));
document.querySelectorAll('[data-spin-view]').forEach(view=>{const image=view.querySelector('[data-spin-image]');const button=view.querySelector('[data-spin-toggle]');const label=view.querySelector('[data-spin-label]');if(!image||!button||!label)return;button.addEventListener('click',()=>{const willPlay=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(willPlay));label.textContent=willPlay?'Arrêter la rotation':'Lancer la rotation';view.classList.toggle('is-playing',willPlay);image.src=willPlay?`${image.dataset.gifSrc}?v=${Date.now()}`:image.dataset.posterSrc})});
document.querySelector('[data-contact-form]')?.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);const subject=`Projet Arcade PHP — ${data.get('type')}`;const body=[`Nom : ${data.get('nom')}`,`Société : ${data.get('societe')||'Non renseignée'}`,`E-mail : ${data.get('email')}`,'',String(data.get('message'))].join('\n');window.location.href=`mailto:contact@arcade-php.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`});
